// Collection controls run only inside the authenticated visual editor.
window.PBEquipmentCollections={render(doc,config,{mark,chooseImage}){
const bind=(el,row,key)=>{el.contentEditable='plaintext-only';el.spellcheck=false;el.dataset.collectionField=key;el.dataset.siteStyle=(Object.hasOwn(row,'question')?'faq:':'card:')+row.id+':'+key;el.textContent=row[key];el.oninput=()=>{row[key]=el.textContent;mark();};el.onpaste=event=>{event.preventDefault();doc.execCommand('insertText',false,event.clipboardData.getData('text/plain'));};};
const button=(label,action)=>{const el=doc.createElement('button');el.type='button';el.textContent=label;el.className='collection-edit-button';el.onclick=event=>{event.preventDefault();action();};return el;};
const draw=()=>{this.render(doc,config,{mark,chooseImage});window.PBSiteTextEditor?.install(doc,config,mark);window.PBSiteLayoutEditor?.install(doc,config,mark);};
const grid=doc.querySelector('.service-grid');if(grid){grid.replaceChildren();for(const row of config.serviceCards){const card=doc.createElement('article');card.className='service-card';card.dataset.siteCard=row.id;const album=doc.createElement('div');album.className='service-album';album.dataset.serviceAlbum='';const gallery=doc.createElement('div');gallery.className='service-card-gallery';for(const [index,src]of row.images.entries()){const box=doc.createElement('div');box.className='collection-image';box.dataset.albumSlide='';const image=doc.createElement('img');image.src=src;image.dataset.cardImage=String(index);image.alt=row.title;image.onclick=()=>chooseImage({cardId:row.id,index});box.append(image,button('حذف تصویر',()=>{row.images.splice(index,1);mark();draw();}));gallery.append(box);}const content=doc.createElement('div');for(const [key,tag]of [['title','h3'],['text','p'],['button','span']]){const el=doc.createElement(tag);bind(el,row,key);content.append(el);}const destination=doc.createElement('select');destination.setAttribute('aria-label','مقصد دکمهٔ '+row.title);for(const [href,label]of [['/products','محصولات'],['/equipment','خدمات تجهیزات'],['/rental-equipment','آفیش تجهیزات'],['/guides','راهنماها'],['/order-guide','راهنمای سفارش'],['/about','دربارهٔ ما'],['/contact','ارتباط']]){const option=doc.createElement('option');option.value=href;option.textContent=label;destination.append(option);}if(![...destination.options].some(x=>x.value===row.href)){const option=doc.createElement('option');option.value=row.href;option.textContent=row.href;destination.append(option);}destination.value=row.href;destination.onchange=()=>{row.href=destination.value;mark();};content.append(destination,button('افزودن تصویر',()=>{if(row.images.length<5)chooseImage({cardId:row.id});}),button('حذف کارت',()=>{config.serviceCards=config.serviceCards.filter(x=>x.id!==row.id);mark();draw();}));album.append(gallery);card.append(album,content);grid.append(card);}grid.append(button('افزودن کارت خدمات',()=>{if(config.serviceCards.length>=12)return;config.serviceCards.push({id:crypto.randomUUID(),title:'خدمت جدید',text:'توضیح خدمت را اینجا بنویسید.',button:'مشاهده',href:'/products',images:[]});mark();draw();}));}
const host=doc.querySelector('[data-equipment-faq-list]');if(host){host.replaceChildren();for(const row of config.faqs){const item=doc.createElement('details');item.className='faq-item';item.open=true;item.dataset.siteFaq=row.id;const summary=doc.createElement('summary'),question=doc.createElement('span'),answer=doc.createElement('p');bind(question,row,'question');bind(answer,row,'answer');summary.append(question);item.append(summary,answer,button('حذف پرسش',()=>{config.faqs=config.faqs.filter(x=>x.id!==row.id);mark();draw();}));host.append(item);}host.append(button('افزودن پرسش',()=>{if(config.faqs.length>=30)return;config.faqs.push({id:crypto.randomUUID(),question:'پرسش جدید',answer:'پاسخ را اینجا بنویسید.'});mark();draw();}));}
doc.defaultView.PBEquipmentAlbum?.enhance(doc);if(!doc.querySelector('#equipment-collection-editor-style')){const style=doc.createElement('style');style.id='equipment-collection-editor-style';style.textContent='.collection-edit-button{font:inherit;font-size:11px;margin:5px;padding:5px 9px;border:1px dashed #315efb;border-radius:7px;background:#eff4ff;color:#2549c0;cursor:pointer}.collection-image{flex:0 0 100%;min-width:0}.collection-image img{width:100%;height:180px;object-fit:cover;cursor:pointer}.service-card [contenteditable],.faq-item [contenteditable]{outline:1px dashed #315efb60;min-height:24px}.service-card select{width:100%;font:inherit;font-size:12px;margin-block:8px}';doc.head.append(style);}
}};
